 add('self_package','s.space.objects[0]=Object {value:Value::Package {first:0,count:1}};',target=0)
 payloads=[('Uninitialized','Value::Uninitialized'),('Integer','Value::Integer {number:18446744073709551615}'),('SourceString','Value::String {string_storage:StringStorage::Source {string_source:Span {unit:99,start:18446744073709551615,end:0}}}'),('OwnedString','Value::String {string_storage:StringStorage::Owned {string_owner:63}}'),('SourceBuffer','Value::Buffer {buffer_storage:BufferStorage::Source {declared_size:18446744073709551615,buffer_initializer:Span {unit:88,start:8,end:1}}}'),('OwnedBuffer','Value::Buffer {buffer_storage:BufferStorage::Owned {buffer_owner:63}}'),('BufferField','Value::BufferField {backing_object:18446744073709551615,bit_offset:18446744073709551615,bit_length:0}'),('Package','Value::Package {first:18446744073709551615,count:18446744073709551615}'),('NameReference','Value::NameReference {name:Path {count:18446744073709551615},scope:Path {parents:18446744073709551615}}'),('Method','Value::Method {flags:255,body:Span {unit:4,start:8,end:2}}'),('Device','Value::Device'),('Processor','Value::Processor {id:255,address:4294967295,length:255}'),('PowerResource','Value::PowerResource {system_level:255,order:65535}'),('ThermalZone','Value::ThermalZone'),('Mutex','Value::Mutex {sync_level:255}'),('Event','Value::Event'),('OperationRegion','Value::OperationRegion {space:255,base:18446744073709551615,length:18446744073709551615,scope:Path {count:17}}')]
 payloads +=[(k,'Value::Reference {kind:ReferenceKind::'+k+',object_id:18446744073709551615}')for k in KINDS]
 for name,payload in payloads:add('element_'+name,f's.space.objects[1].value={payload};')
 add('alias_package','s.space.objects[4]=Object {value:Value::Package {first:1,count:3}};s.space.object_count=5;',package=4)
