IMPORTS='use aml::model::ObjectStore;\nuse aml::model::Namespace;\nuse aml::model::Value;\nuse aml::model::Object;\nuse aml::model::Entry;\nuse aml::model::Path;\nuse aml::model::Span;\nuse aml::model::ByteBlock;\nuse aml::model::StringStorage;\nuse aml::model::BufferStorage;\nuse aml::model::ReferenceKind;\nuse aml::model::Outcome;\nuse aml::model::Read;\nuse aml::package_index::make_package_index;\n'
HELPERS='machine seed()->ObjectStore {\n let mut s:ObjectStore=ObjectStore {};s.space.count=2;s.space.object_count=4;\n let mut bytes:[u8;256];seed_bytes(&mut bytes,0,256);seed_slots(&mut s,bytes,0,64);seed_entries(&mut s,0,32);\n s.space.objects[0]=Object {value:Value::Package {first:1,count:3}};\n s.space.objects[1]=Object {value:Value::Integer {number:44},has_next:true,next:2};\n s.space.objects[2]=Object {value:Value::String {string_storage:StringStorage::Owned {string_owner:63}},has_next:true,next:3};\n s.space.objects[3]=Object {value:Value::NameReference {name:Path {count:17},scope:Path {parents:18446744073709551615}}};s\n}\nmachine seed_bytes(a:&mut [u8;256],i:u64,n:u64) terminates by(i,n)->Nat::BoundedDistance; {seed_byte(a,i);transition i<n {true -> seed_bytes(a,i+1,n) _ -> {}}}\nmachine seed_byte(a:&mut [u8;256],i:u64){transition i<256 {true -> put(a,i) _ -> {}} state put(a:&mut [u8;256],i:u64){a[i]=(i^165) as u8;}}\nmachine seed_slots(s:&mut ObjectStore,bytes:[u8;256],i:u64,n:u64) terminates by(i,n)->Nat::BoundedDistance; {seed_slot(s,bytes,i);transition i<n {true -> seed_slots(s,bytes,i+1,n) _ -> {}}}\nmachine seed_slot(s:&mut ObjectStore,bytes:[u8;256],i:u64){transition i<64 {true -> put(s,bytes,i) _ -> {}} state put(s:&mut ObjectStore,bytes:[u8;256],i:u64){s.space.objects[i]=Object {value:Value::Integer {number:1000+i},has_next:true,next:18446744073709551615-i};s.bytes.blocks[i]=ByteBlock {initialized:true,length:18446744073709551615-i,bytes:bytes};}}\nmachine seed_entries(s:&mut ObjectStore,i:u64,n:u64) terminates by(i,n)->Nat::BoundedDistance; {seed_entry(s,i);transition i<n {true -> seed_entries(s,i+1,n) _ -> {}}}\nmachine seed_entry(s:&mut ObjectStore,i:u64){transition i<32 {true -> put(s,i) _ -> {}} state put(s:&mut ObjectStore,i:u64){s.space.entries[i]=Entry {path:Path {parents:18446744073709551615,count:i},has_object:true,object:i,alias:true};s.space.entries[i].path.segments[15]=3735928559;}}\nmachine long_chain(s:&mut ObjectStore){s.space.object_count=63;s.space.objects[0].value=Value::Package {first:1,count:62};long_nodes(s,1,63);}\nmachine long_nodes(s:&mut ObjectStore,i:u64,n:u64) terminates by(i,n)->Nat::BoundedDistance; {long_node(s,i);transition i<n {true -> long_nodes(s,i+1,n) _ -> {}}}\nmachine long_node(s:&mut ObjectStore,i:u64){transition i>0 && i<63 {true -> put(s,i) _ -> {}} state put(s:&mut ObjectStore,i:u64){s.space.objects[i]=Object {value:Value::Integer {number:i},has_next:i<62,next:i+1};}}\nmachine span_same(a:Span,b:Span)->bool {a.unit==b.unit && a.start==b.start && a.end==b.end}\nmachine path_same(a:Path,b:Path)->bool {let same:bool=segments(a,b,0,16,true);same && a.absolute==b.absolute && a.parents==b.parents && a.count==b.count}\nmachine segments(a:Path,b:Path,i:u64,n:u64,good:bool) terminates by(i,n)->Nat::BoundedDistance; ->bool {let same:bool=segment(a,b,i);transition i<n {true -> segments(a,b,i+1,n,good && same) _ -> (good)}}\nmachine segment(a:Path,b:Path,i:u64)->bool {transition i<16 {true -> (a.segments[i]==b.segments[i]) _ -> (true)}}\nmachine string_same(a:StringStorage,b:StringStorage)->bool {transition a {StringStorage::Source {string_source} -> source(string_source,b) StringStorage::Owned {string_owner} -> owned(string_owner,b)} state source(a:Span,b:StringStorage)->bool {transition b {StringStorage::Source {string_source} -> compare(a,string_source) _ -> (false)}} state compare(a:Span,b:Span)->bool {let good:bool=span_same(a,b);good} state owned(a:u64,b:StringStorage)->bool {transition b {StringStorage::Owned {string_owner} -> (a==string_owner) _ -> (false)}}}\nmachine buffer_same(a:BufferStorage,b:BufferStorage)->bool {transition a {BufferStorage::Source {declared_size,buffer_initializer} -> source(declared_size,buffer_initializer,b) BufferStorage::Owned {buffer_owner} -> owned(buffer_owner,b)} state source(size:u64,span:Span,b:BufferStorage)->bool {transition b {BufferStorage::Source {declared_size,buffer_initializer} -> compare(size,span,declared_size,buffer_initializer) _ -> (false)}} state compare(a:u64,s:Span,b:u64,t:Span)->bool {let good:bool=span_same(s,t);good && a==b} state owned(a:u64,b:BufferStorage)->bool {transition b {BufferStorage::Owned {buffer_owner} -> (a==buffer_owner) _ -> (false)}}}\nmachine value_same(a:Value,b:Value)->bool {transition a {Value::Uninitialized -> uninitialized(b) Value::Integer {number} -> integer(number,b) Value::String {string_storage} -> string(string_storage,b) Value::Buffer {buffer_storage} -> buffer(buffer_storage,b) Value::BufferField {backing_object,bit_offset,bit_length} -> bufferfield(backing_object,bit_offset,bit_length,b) Value::Package {first,count} -> package(first,count,b) Value::NameReference {name,scope} -> namereference(name,scope,b) Value::Reference {kind,object_id} -> reference(kind,object_id,b) Value::Method {flags,body} -> method(flags,body,b) Value::Device -> device(b) Value::Processor {id,address,length} -> processor(id,address,length,b) Value::PowerResource {system_level,order} -> powerresource(system_level,order,b) Value::ThermalZone -> thermalzone(b) Value::Mutex {sync_level} -> mutex(sync_level,b) Value::Event -> event(b) Value::OperationRegion {space,base,length,scope} -> operationregion(space,base,length,scope,b) }\nstate uninitialized(b:Value)->bool {transition b {Value::Uninitialized -> compare_uninitialized() _ -> (false)}}\nstate compare_uninitialized()->bool {true}\nstate integer(anumber:u64,b:Value)->bool {transition b {Value::Integer {number} -> compare_integer(anumber,number) _ -> (false)}}\nstate compare_integer(anumber:u64,number:u64)->bool {anumber==number}\nstate string(astring_storage:StringStorage,b:Value)->bool {transition b {Value::String {string_storage} -> compare_string(astring_storage,string_storage) _ -> (false)}}\nstate compare_string(astring_storage:StringStorage,string_storage:StringStorage)->bool {let cstring_storage:bool=string_same(astring_storage,string_storage);cstring_storage}\nstate buffer(abuffer_storage:BufferStorage,b:Value)->bool {transition b {Value::Buffer {buffer_storage} -> compare_buffer(abuffer_storage,buffer_storage) _ -> (false)}}\nstate compare_buffer(abuffer_storage:BufferStorage,buffer_storage:BufferStorage)->bool {let cbuffer_storage:bool=buffer_same(abuffer_storage,buffer_storage);cbuffer_storage}\nstate bufferfield(abacking_object:u64,abit_offset:u64,abit_length:u64,b:Value)->bool {transition b {Value::BufferField {backing_object,bit_offset,bit_length} -> compare_bufferfield(abacking_object,abit_offset,abit_length,backing_object,bit_offset,bit_length) _ -> (false)}}\nstate compare_bufferfield(abacking_object:u64,abit_offset:u64,abit_length:u64,backing_object:u64,bit_offset:u64,bit_length:u64)->bool {abacking_object==backing_object && abit_offset==bit_offset && abit_length==bit_length}\nstate package(afirst:u64,acount:u64,b:Value)->bool {transition b {Value::Package {first,count} -> compare_package(afirst,acount,first,count) _ -> (false)}}\nstate compare_package(afirst:u64,acount:u64,first:u64,count:u64)->bool {afirst==first && acount==count}\nstate namereference(aname:Path,ascope:Path,b:Value)->bool {transition b {Value::NameReference {name,scope} -> compare_namereference(aname,ascope,name,scope) _ -> (false)}}\nstate compare_namereference(aname:Path,ascope:Path,name:Path,scope:Path)->bool {let cname:bool=path_same(aname,name);let cscope:bool=path_same(ascope,scope);cname && cscope}\nstate reference(akind:ReferenceKind,aobject_id:u64,b:Value)->bool {transition b {Value::Reference {kind,object_id} -> compare_reference(akind,aobject_id,kind,object_id) _ -> (false)}}\nstate compare_reference(akind:ReferenceKind,aobject_id:u64,kind:ReferenceKind,object_id:u64)->bool {akind==kind && aobject_id==object_id}\nstate method(aflags:u8,abody:Span,b:Value)->bool {transition b {Value::Method {flags,body} -> compare_method(aflags,abody,flags,body) _ -> (false)}}\nstate compare_method(aflags:u8,abody:Span,flags:u8,body:Span)->bool {let cbody:bool=span_same(abody,body);aflags==flags && cbody}\nstate device(b:Value)->bool {transition b {Value::Device -> compare_device() _ -> (false)}}\nstate compare_device()->bool {true}\nstate processor(aid:u8,aaddress:u32,alength:u8,b:Value)->bool {transition b {Value::Processor {id,address,length} -> compare_processor(aid,aaddress,alength,id,address,length) _ -> (false)}}\nstate compare_processor(aid:u8,aaddress:u32,alength:u8,id:u8,address:u32,length:u8)->bool {aid==id && aaddress==address && alength==length}\nstate powerresource(asystem_level:u8,aorder:u16,b:Value)->bool {transition b {Value::PowerResource {system_level,order} -> compare_powerresource(asystem_level,aorder,system_level,order) _ -> (false)}}\nstate compare_powerresource(asystem_level:u8,aorder:u16,system_level:u8,order:u16)->bool {asystem_level==system_level && aorder==order}\nstate thermalzone(b:Value)->bool {transition b {Value::ThermalZone -> compare_thermalzone() _ -> (false)}}\nstate compare_thermalzone()->bool {true}\nstate mutex(async_level:u8,b:Value)->bool {transition b {Value::Mutex {sync_level} -> compare_mutex(async_level,sync_level) _ -> (false)}}\nstate compare_mutex(async_level:u8,sync_level:u8)->bool {async_level==sync_level}\nstate event(b:Value)->bool {transition b {Value::Event -> compare_event() _ -> (false)}}\nstate compare_event()->bool {true}\nstate operationregion(aspace:u8,abase:u64,alength:u64,ascope:Path,b:Value)->bool {transition b {Value::OperationRegion {space,base,length,scope} -> compare_operationregion(aspace,abase,alength,ascope,space,base,length,scope) _ -> (false)}}\nstate compare_operationregion(aspace:u8,abase:u64,alength:u64,ascope:Path,space:u8,base:u64,length:u64,scope:Path)->bool {let cscope:bool=path_same(ascope,scope);aspace==space && abase==base && alength==length && cscope}\n}\nmachine object_same(a:Object,b:Object)->bool {let same:bool=value_same(a.value,b.value);same && a.has_next==b.has_next && a.next==b.next}\nmachine entry_same(a:Entry,b:Entry)->bool {let same:bool=path_same(a.path,b.path);same && a.has_level==b.has_level && a.has_object==b.has_object && a.level==b.level && a.object==b.object && a.alias==b.alias}\nmachine entries(a:&ObjectStore,b:&ObjectStore,i:u64,n:u64,good:bool) terminates by(i,n)->Nat::BoundedDistance; ->bool {let same:bool=entry_equal_at(a,b,i);transition i<n {true -> entries(a,b,i+1,n,good && same) _ -> (good)}}\nmachine entry_equal_at(a:&ObjectStore,b:&ObjectStore,i:u64)->bool {transition i<32 {true -> compare(a.space.entries[i],b.space.entries[i]) _ -> (true)} state compare(a:Entry,b:Entry)->bool {let same:bool=entry_same(a,b);same}}\nmachine objects(a:&ObjectStore,b:&ObjectStore,i:u64,n:u64,good:bool) terminates by(i,n)->Nat::BoundedDistance; ->bool {let same:bool=slot(a,b,i);transition i<n {true -> objects(a,b,i+1,n,good && same) _ -> (good)}}\nmachine slot(a:&ObjectStore,b:&ObjectStore,i:u64)->bool {transition i<64 {true -> compare(a.space.objects[i],b.space.objects[i],a.bytes.blocks[i],b.bytes.blocks[i]) _ -> (true)} state compare(a:Object,b:Object,x:ByteBlock,y:ByteBlock)->bool {let same:bool=object_same(a,b);let bytes:bool=block_bytes(&x.bytes,&y.bytes,0,256,true);same && bytes && x.initialized==y.initialized && x.length==y.length}}\nmachine block_bytes(a:&[u8;256],b:&[u8;256],i:u64,n:u64,good:bool) terminates by(i,n)->Nat::BoundedDistance; ->bool {let same:bool=block_byte(a,b,i);transition i<n {true -> block_bytes(a,b,i+1,n,good && same) _ -> (good)}}\nmachine block_byte(a:&[u8;256],b:&[u8;256],i:u64)->bool {transition i<256 {true -> (a[i]==b[i]) _ -> (true)}}\nmachine check(store:ObjectStore,expected:ObjectStore,package:u64,index:u64,repeat:u64,outcome:Outcome,result:u64)->i32 {\n let mut actual:ObjectStore=store;let first:Read=make_package_index(&mut actual,package,index);\n transition repeat==2 {true -> twice(actual,expected,package,index,outcome,result,first,store.space.object_count) _ -> compare(actual,expected,first,outcome,result)}\n state twice(store:ObjectStore,expected:ObjectStore,package:u64,index:u64,outcome:Outcome,result:u64,first:Read,first_id:u64)->i32 {\n  let mut actual:ObjectStore=store;let second:Read=make_package_index(&mut actual,package,index);\n  transition first.outcome==Outcome::Success && first.value==first_id && first.next==0 && first.offset==0 {true -> compare(actual,expected,second,outcome,result) _ -> (1)}\n }\n state compare(actual:ObjectStore,expected:ObjectStore,result:Read,outcome:Outcome,id:u64)->i32 {\n  let e:bool=entries(&actual,&expected,0,32,true);let o:bool=objects(&actual,&expected,0,64,true);\n  transition e && o && actual.space.count==expected.space.count && actual.space.object_count==expected.space.object_count && result.outcome==outcome && result.value==id && result.next==0 && result.offset==0 {true -> (0) _ -> (1)}\n }\n}\nmachine expected_write(s:&mut ObjectStore,at:u64,target:u64){transition at<64 {true -> put(s,at,target) _ -> {}} state put(s:&mut ObjectStore,at:u64,target:u64){s.space.objects[at]=Object {value:Value::Reference {kind:ReferenceKind::RefOf,object_id:target}};s.space.object_count=at+1;}}\n'
def body(row,control=False):
 t='let mut s:ObjectStore=seed();'+row['mutation']+'let mut expected:ObjectStore=s;'
 success= row['outcome']=='Success'
 allocations=row['repeat']if success else(1 if row['name']=='repeat_exhausts'else 0)
 for i in range(allocations):
  t+=f'let at{i}:u64=expected.space.object_count;'
  # All successful fixture metadata has at<64; explicit local bounds keep Omega index proofs.
  t+=f'expected_write(&mut expected,at{i},{row["target"]});'
 t+='let expected_id:u64=' +(f'at{allocations-1};'if success else'0;')
 if control:
  if success:
   mode=sum(row['name'].encode())%4
   if mode==0:t+='expected.bytes.blocks[63].bytes[255]=0;'
   elif mode==1:t+='expected.space.object_count=0;'
   else:t+=f'control_reference(&mut expected,at{allocations-1},{row["target"]},{str(mode==2).lower()});'
  else:t+='expected.space.objects[63].next=expected.space.objects[63].next^1;'
 t+=f'let answer:i32=check(s,expected,{row["package"]},{row["index"]},{row["repeat"]},Outcome::{row["outcome"]},expected_id);answer'
 return t

HELPERS+='machine control_reference(s:&mut ObjectStore,at:u64,target:u64,kind:bool){transition at<64 {true -> put(s,at,target,kind) _ -> {}} state put(s:&mut ObjectStore,at:u64,target:u64,kind:bool){transition kind {true -> wrong_kind(s,at,target) _ -> wrong_target(s,at,target)}} state wrong_kind(s:&mut ObjectStore,at:u64,target:u64){s.space.objects[at].value=Value::Reference {kind:ReferenceKind::Index,object_id:target};} state wrong_target(s:&mut ObjectStore,at:u64,target:u64){s.space.objects[at].value=Value::Reference {kind:ReferenceKind::RefOf,object_id:target^1};}}'

HELPERS+='\nmachine const_slots(a:&ObjectStore,b:&ObjectStore,i:u64,n:u64,good:bool) terminates by(i,n)->Nat::BoundedDistance; ->bool {let same:bool=const_slot(a,b,i);transition i<n {true -> const_slots(a,b,i+1,n,good && same) _ -> (good)}}\nmachine const_slot(a:&ObjectStore,b:&ObjectStore,i:u64)->bool {transition i<64 {true -> compare(a.space.objects[i],b.space.objects[i],a.bytes.blocks[i],b.bytes.blocks[i]) _ -> (true)} state compare(a:Object,b:Object,x:ByteBlock,y:ByteBlock)->bool {let same:bool=object_same(a,b);same && x.initialized==y.initialized && x.length==y.length && x.bytes[0]==y.bytes[0] && x.bytes[255]==y.bytes[255]}}\nmachine const_check(store:ObjectStore,expected:ObjectStore,package:u64,index:u64,repeat:u64,outcome:Outcome,id:u64)->i32 {\n let mut actual:ObjectStore=store;let result:Read=make_package_index(&mut actual,package,index);\n let e:bool=entries(&actual,&expected,0,32,true);let o:bool=const_slots(&actual,&expected,0,64,true);\n transition repeat==1 && e && o && actual.space.count==expected.space.count && actual.space.object_count==expected.space.object_count && result.outcome==outcome && result.value==id && result.next==0 && result.offset==0 {true -> (0) _ -> (1)}\n}\n'
